<?php

declare(strict_types=1);

// Serves uploaded photos from storage/uploads (outside the web root). Only names generated by
// ImageService are accepted, so no other file can be read through this script.

use App\Services\ImageService;

require __DIR__ . '/boot.php';

// Release the session lock at once so a page with many photos loads them in parallel.
session_write_close();

$name = $_GET['f'] ?? '';
$path = is_string($name) ? (new ImageService())->path($name) : null;
if ($path === null) {
    http_response_code(404);
    exit;
}

// File names are random and never reused, so browsers may cache them forever.
header('Content-Type: image/webp');
header('Content-Length: ' . filesize($path));
header('Cache-Control: public, max-age=31536000, immutable');
readfile($path);
